import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{r as i,o as c,c as l,a as n,b as s,d as e,e as o}from"./app-401f6a81.js";const p={},r=o(`<h1 id="cling-基于-llvm-的-c-交互式解释器" tabindex="-1"><a class="header-anchor" href="#cling-基于-llvm-的-c-交互式解释器" aria-hidden="true">#</a> cling（基于 LLVM 的 C++ 交互式解释器）</h1><blockquote><p>Homebrew 版本 1.2 ｜ 主页：见官方文档 ｜ 安装：<code>brew install cling</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>cling 是一个基于 <strong>LLVM/Clang</strong> 的 C++ 交互式解释器（interactive C++ interpreter），它提供了类似 Python 的 REPL 体验，但运行的是<strong>原生 C++</strong>。它解决的核心问题是：你不需要先写一个完整的 <code>.cpp</code> 文件、编译、链接、运行这一整套繁琐流程，就能逐行（或逐块）执行 C++ 表达式、声明变量、定义函数、包含头文件，并立即看到结果。</p><p>典型应用场景包括：快速验证算法逻辑、调试某段 C++ 代码片段、在交互式环境中探索 C++ 标准库和第三方库的 API、教学演示 C++ 语法、以及在科研或数据分析场景中把 C++ 当作脚本语言来使用。cling 也常作为 ROOT（CERN 的粒子物理分析框架）的底层解释引擎，把 C++ 代码直接绑定成可交互执行的脚本。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>通过 Homebrew 安装 cling：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> cling

<span class="token comment"># 升级到最新版本</span>
brew upgrade cling

<span class="token comment"># 查看当前安装的版本</span>
cling <span class="token parameter variable">--version</span>

<span class="token comment"># 卸载</span>
brew uninstall cling
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证安装是否成功：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接进入交互式解释器</span>
cling

<span class="token comment"># 或查看版本信息</span>
cling <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果 <code>brew install cling</code> 报错找不到包，可先执行 <code>brew update</code> 更新 Homebrew 的配方索引，再重试安装。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令 / 语法</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>cling</code></td><td>启动交互式 REPL</td><td><code>cling</code></td></tr><tr><td><code>cling --version</code></td><td>显示版本与 LLVM 信息</td><td><code>cling --version</code></td></tr><tr><td><code>cling 脚本.cpp</code></td><td>直接运行一个 C++ 源文件</td><td><code>cling demo.cpp</code></td></tr><tr><td><code>cling -l 库名</code> / <code>#include &lt;库&gt;</code></td><td>加载/包含头文件或库</td><td><code>cling -lstdc++</code></td></tr><tr><td><code>#include &lt;vector&gt;</code></td><td>在 REPL 内包含标准库头文件</td><td>在 cling 里输入 <code>#include &lt;vector&gt;</code></td></tr><tr><td><code>#pragma cling</code></td><td>各种 cling 扩展指令</td><td>见下文进阶技巧</td></tr><tr><td><code>.q</code> 或 <code>.quit</code></td><td>退出 cling 交互式会话</td><td>在 REPL 里输入 <code>.q</code></td></tr><tr><td><code>.help</code></td><td>查看内置命令帮助</td><td>在 REPL 里输入 <code>.help</code></td></tr><tr><td><code>.L 文件名.cpp</code></td><td>加载并解析一个文件到当前会话</td><td>在 REPL 里输入 <code>.L mylib.cpp</code></td></tr><tr><td><code>Ctrl+D</code></td><td>退出 REPL（EOF）</td><td>直接按 <code>Ctrl+D</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-进入-repl-并执行基本表达式" tabindex="-1"><a class="header-anchor" href="#示例-1-进入-repl-并执行基本表达式" aria-hidden="true">#</a> 示例 1：进入 REPL 并执行基本表达式</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 启动 cling</span>
cling

<span class="token comment"># 在 cling 提示符下输入以下内容（无需编译，逐行立即执行）</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int a <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int b <span class="token operator">=</span> <span class="token number">20</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> a + b
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>const int<span class="token punctuation">)</span> <span class="token number">30</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token keyword">for</span> <span class="token punctuation">(</span>int i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> <span class="token number">3</span><span class="token punctuation">;</span> ++i<span class="token punctuation">)</span> <span class="token punctuation">{</span> std::cout <span class="token operator">&lt;&lt;</span> i <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; &quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token number">0</span> <span class="token number">1</span> <span class="token number">2</span> 
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .q
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>说明：<code>cling-1&gt;</code> 是 cling 的交互提示符。每行输入 <code>;</code> 结尾的语句会立即求值；表达式（不带分号）会打印结果。<code>(const int) 30</code> 即 <code>a + b</code> 的求值结果。按 <code>.q</code> 退出。</p></blockquote><h3 id="示例-2-在-repl-中使用标准库容器与算法" tabindex="-1"><a class="header-anchor" href="#示例-2-在-repl-中使用标准库容器与算法" aria-hidden="true">#</a> 示例 2：在 REPL 中使用标准库容器与算法</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;vector&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;algorithm&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> std::vector<span class="token operator">&lt;</span>int<span class="token operator">&gt;</span> <span class="token function">v</span> <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token number">3</span>, <span class="token number">1</span>, <span class="token number">4</span>, <span class="token number">1</span>, <span class="token number">5</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> std::sort<span class="token punctuation">(</span>v.begin<span class="token punctuation">(</span><span class="token punctuation">)</span>, v.end<span class="token punctuation">(</span><span class="token punctuation">))</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token keyword">for</span> <span class="token punctuation">(</span>int x <span class="token builtin class-name">:</span> <span class="token function">v</span><span class="token punctuation">)</span> std::cout <span class="token operator">&lt;&lt;</span> x <span class="token operator">&lt;&lt;</span> <span class="token string">&quot; &quot;</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token number">1</span> <span class="token number">1</span> <span class="token number">3</span> <span class="token number">4</span> <span class="token number">5</span> 
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .q
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-编写脚本文件并直接运行" tabindex="-1"><a class="header-anchor" href="#示例-3-编写脚本文件并直接运行" aria-hidden="true">#</a> 示例 3：编写脚本文件并直接运行</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先创建一个 C++ 脚本文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> hello_cling.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
#include &lt;iostream&gt;
#include &lt;string&gt;

std::string greet(const std::string&amp; name) {
    return &quot;Hello, &quot; + name + &quot;!&quot;;
}

int main() {
    std::cout &lt;&lt; greet(&quot;cling&quot;) &lt;&lt; std::endl;
    return 0;
}
EOF</span>

<span class="token comment"># 用 cling 直接运行（不需要手动编译链接）</span>
cling hello_cling.cpp
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>Hello, cling<span class="token operator">!</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="示例-4-repl-内加载并复用自定义源文件" tabindex="-1"><a class="header-anchor" href="#示例-4-repl-内加载并复用自定义源文件" aria-hidden="true">#</a> 示例 4：REPL 内加载并复用自定义源文件</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备一个工具函数文件</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> math_util.cpp <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
int square(int x) { return x * x; }
int cube(int x) { return x * x * x; }
EOF</span>

<span class="token comment"># 在 cling 会话中加载它并调用</span>
cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .L math_util.cpp
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> square<span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">25</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> cube<span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">27</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> .q
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><code>.L 文件名</code> 会把文件内容解析进当前会话，之后定义的函数/变量即可直接使用。</p></blockquote><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_1-在-repl-内定义函数与类-实现-热插拔-式开发" tabindex="-1"><a class="header-anchor" href="#_1-在-repl-内定义函数与类-实现-热插拔-式开发" aria-hidden="true">#</a> 1. 在 REPL 内定义函数与类，实现&quot;热插拔&quot;式开发</h3><p>cling 支持在会话中随时重定义函数。若某个函数签名相同、实现变化，直接重新输入定义即可覆盖旧版本，非常适合边改边测：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int add<span class="token punctuation">(</span>int a, int b<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token builtin class-name">return</span> a + b<span class="token punctuation">;</span> <span class="token punctuation">}</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> add<span class="token punctuation">(</span><span class="token number">2</span>, <span class="token number">3</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">5</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> int add<span class="token punctuation">(</span>int a, int b<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token builtin class-name">return</span> a + b * <span class="token number">10</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>   // 重新定义
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> add<span class="token punctuation">(</span><span class="token number">2</span>, <span class="token number">3</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">32</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-使用-pragma-cling-扩展指令控制加载与编译" tabindex="-1"><a class="header-anchor" href="#_2-使用-pragma-cling-扩展指令控制加载与编译" aria-hidden="true">#</a> 2. 使用 <code>#pragma cling</code> 扩展指令控制加载与编译</h3><p>cling 提供了一组 <code>#pragma cling</code> 指令，用于更精细地控制代码加载、优化和声明：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

<span class="token comment"># 临时关闭优化，方便调试</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling opt(0)</span>
<span class="token comment"># 加载共享库（链接动态库，例如某个 .so）</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling load(&quot;libmymodule.so&quot;)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在源文件里也可以直接写这些 pragma 指令，实现&quot;编译时控制&quot;。</p><h3 id="_3-与-make-cmake-产出的对象或库配合" tabindex="-1"><a class="header-anchor" href="#_3-与-make-cmake-产出的对象或库配合" aria-hidden="true">#</a> 3. 与 Make / CMake 产出的对象或库配合</h3><p>如果项目已经用 CMake 编译出静态库或动态库，你可以在 cling 会话中加载头文件并链接库，直接调用其 API 进行探索：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling

<span class="token comment"># 假设项目产出 libmymath.a</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &quot;mymath.h&quot;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#pragma cling load(&quot;libmymath.a&quot;)</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> mymath::add<span class="token punctuation">(</span><span class="token number">10</span>, <span class="token number">32</span><span class="token punctuation">)</span>
cling-<span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span> <span class="token punctuation">(</span>int<span class="token punctuation">)</span> <span class="token number">42</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-与其它工具搭配-在脚本中使用第三方-c-库" tabindex="-1"><a class="header-anchor" href="#_4-与其它工具搭配-在脚本中使用第三方-c-库" aria-hidden="true">#</a> 4. 与其它工具搭配：在脚本中使用第三方 C++ 库</h3><p>结合 Homebrew 安装的 C++ 库（如 <code>boost</code>、<code>eigen</code>），可以像脚本一样调用它们：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 先安装依赖库</span>
brew <span class="token function">install</span> boost eigen

cling

cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> <span class="token comment">#include &lt;eigen3/Eigen/Dense&gt;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> Eigen::MatrixXd m<span class="token punctuation">(</span><span class="token number">2</span>, <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> m <span class="token operator">&lt;&lt;</span> <span class="token number">1</span>, <span class="token number">2</span>, <span class="token number">3</span>, <span class="token number">4</span><span class="token punctuation">;</span>
cling-<span class="token operator"><span class="token file-descriptor important">1</span>&gt;</span> m.inverse<span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：Eigen 等头文件库通常位于 <code>/opt/homebrew/include</code> 或 <code>/usr/local/include</code>，如果找不到，可以用 <code>-I</code> 指定头文件搜索路径：<code>cling -I/opt/homebrew/include</code> 或在 REPL 里用 <code>#pragma cling add_include_path</code> 添加。</p></blockquote><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_1-交互式-repl-里表达式与语句的区别" tabindex="-1"><a class="header-anchor" href="#_1-交互式-repl-里表达式与语句的区别" aria-hidden="true">#</a> 1. 交互式 REPL 里表达式与语句的区别</h3><ul><li><strong>语句</strong>以分号 <code>;</code> 结尾：执行但不打印结果（<code>int a = 10;</code>）。</li><li><strong>表达式</strong>不带分号：立即求值并打印结果（<code>a + b</code>）。</li><li>新手最常见的坑是在 REPL 里打表达式时带了分号，结果什么也没输出——去掉分号再回车即可看到结果。</li></ul><h3 id="_2-版本与-llvm-依赖问题" tabindex="-1"><a class="header-anchor" href="#_2-版本与-llvm-依赖问题" aria-hidden="true">#</a> 2. 版本与 LLVM 依赖问题</h3><p>cling 依赖特定版本的 LLVM/Clang。若 <code>brew upgrade</code> 后 LLVM 版本与 cling 不匹配，可能出现加载头文件失败或奇怪崩溃。此时建议：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>brew doctor
brew upgrade cling
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>并确认 <code>cling --version</code> 显示的 LLVM 版本与 <code>clang --version</code> 一致。</p><h3 id="_3-头文件包含失败-找不到标准库头文件" tabindex="-1"><a class="header-anchor" href="#_3-头文件包含失败-找不到标准库头文件" aria-hidden="true">#</a> 3. 头文件包含失败 / 找不到标准库头文件</h3><p>若 <code>#include &lt;vector&gt;</code> 等报错找不到头文件，通常是编译器搜索路径配置问题。可显式指定路径：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cling -I/opt/homebrew/include -I/opt/homebrew/include/c++/11.1.0
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><blockquote><p>Apple Silicon 机器用 <code>/opt/homebrew</code>，Intel 机器用 <code>/usr/local</code>。</p></blockquote><h3 id="_4-性能注意" tabindex="-1"><a class="header-anchor" href="#_4-性能注意" aria-hidden="true">#</a> 4. 性能注意</h3><p>cling 是解释/即时编译执行，<strong>速度远低于编译优化的二进制</strong>。CPU 密集的循环代码不要依赖 cling 跑性能基准；它更适合验证逻辑和交互调试。若追求性能，应把代码编译成可执行文件再运行。</p><h3 id="_5-多行代码的粘贴问题" tabindex="-1"><a class="header-anchor" href="#_5-多行代码的粘贴问题" aria-hidden="true">#</a> 5. 多行代码的粘贴问题</h3><p>在 REPL 里直接粘贴多行代码（如整个 <code>for</code> 循环）可能因换行/缩进被错误解析。建议：把完整代码写成 <code>.cpp</code> 文件，用 <code>.L 文件.cpp</code> 或 <code>cling 文件.cpp</code> 加载，而不是直接在交互式提示符粘贴大段代码。</p><h3 id="_6-平台支持差异" tabindex="-1"><a class="header-anchor" href="#_6-平台支持差异" aria-hidden="true">#</a> 6. 平台支持差异</h3>`,57),d=n("code",null,"cling --version",-1),u={href:"https://github.com/root-project/cling",target:"_blank",rel:"noopener noreferrer"},m=n("h2",{id:"参考资料",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#参考资料","aria-hidden":"true"},"#"),s(" 参考资料")],-1),v={href:"https://github.com/root-project/cling",target:"_blank",rel:"noopener noreferrer"},b={href:"https://root.cern.ch",target:"_blank",rel:"noopener noreferrer"},g=n("li",null,[s("Homebrew 配方："),n("code",null,"brew info cling")],-1);function k(h,f){const a=i("ExternalLinkIcon");return c(),l("div",null,[r,n("p",null,[s("cling 在 macOS（Apple Silicon）和 Linux 上的行为基本一致，但部分依赖 LLVM 的第三方扩展可能存在差异。遇到异常时，先确认 "),d,s(" 输出的 LLVM 版本号，并在"),n("a",u,[s("官方 GitHub 仓库"),e(a)]),s("的 Issues 里检索类似问题。")]),m,n("ul",null,[n("li",null,[s("cling 官方仓库："),n("a",v,[s("https://github.com/root-project/cling"),e(a)])]),n("li",null,[s("ROOT 项目（cling 的主要使用者）："),n("a",b,[s("https://root.cern.ch"),e(a)])]),g])])}const L=t(p,[["render",k],["__file","cling.html.vue"]]);export{L as default};
